arguments.command:
python3 - <<'EOF'
H = "# deploy report 2026-08-14 build 118 (api-server)"
E1 = "ERROR 09:14:33 container api-2 failed health check /readyz after 30s"
E2 = "ERROR 09:15:02 rollback of api-2 incomplete: volume detach timed out"
E3 = "ERROR 09:16:40 build 118 marked bad; pipeline halted at stage staging"

strs = {'H':H,'E1':E1,'E2':E2,'E3':E3}

def max_overlap(a,b):
    # max k such that suffix of a (len k) == prefix of b (len k)
    best=0
    for k in range(1, min(len(a),len(b))+1):
        if a[-k:]==b[:k]:
            best=k
    return best

for na,a in strs.items():
    for nb,b in strs.items():
        if na!=nb:
            k = max_overlap(a,b)
            if k>0:
                print(na,nb,k)
print("lengths", {k:len(v) for k,v in strs.items()})
print("total", sum(len(v) for v in strs.values()))
EOF
